// src/telegram.d.ts
export interface TelegramThemeParams {
  bg_color?: string;
  text_color?: string;
  hint_color?: string;
  link_color?: string;
  button_color?: string;
  button_text_color?: string;
  secondary_bg_color?: string;
  section_bg_color?: string;
  destructive_text_color?: string;
}

export interface TelegramWebAppButton {
  text: string;
  isVisible: boolean;
  isActive: boolean;
  isProgressVisible: boolean;
  setText(text: string): void;
  onClick(cb: () => void): void;
  offClick(cb: () => void): void;
  show(): void;
  hide(): void;
  enable(): void;
  disable(): void;
  showProgress(leaveActive?: boolean): void;
  hideProgress(): void;
}

export interface TelegramBackButton {
  isVisible: boolean;
  onClick(cb: () => void): void;
  offClick(cb: () => void): void;
  show(): void;
  hide(): void;
}

export interface TelegramHaptic {
  impactOccurred(style: 'light' | 'medium' | 'heavy' | 'rigid' | 'soft'): void;
  notificationOccurred(type: 'error' | 'success' | 'warning'): void;
  selectionChanged(): void;
}

export interface TelegramWebApp {
  themeParams: TelegramThemeParams;
  viewportStableHeight: number;
  safeAreaInset?: { top: number; bottom: number; left: number; right: number };
  contentSafeAreaInset?: { top: number; bottom: number; left: number; right: number };
  MainButton: TelegramWebAppButton;
  BackButton: TelegramBackButton;
  HapticFeedback: TelegramHaptic;
  isVersionAtLeast(version: string): boolean;
  expand(): void;
  showAlert(message: string, callback?: () => void): void;
  showPopup(
    params: { title?: string; message: string; buttons?: Array<{ id?: string; type?: string; text?: string }> },
    callback?: (buttonId: string) => void
  ): void;
  enableClosingConfirmation(): void;
  disableClosingConfirmation(): void;
  onEvent(event: 'themeChanged' | 'viewportChanged', cb: () => void): void;
  offEvent(event: 'themeChanged' | 'viewportChanged', cb: () => void): void;
}

declare global {
  interface Window {
    Telegram?: { WebApp: TelegramWebApp };
  }
}
