// src/hooks/useTelegramWebApp.ts
import { useEffect, useState } from 'react';
import type { TelegramWebApp } from '../telegram';

export function useTelegramWebApp() {
  const webApp = typeof window !== 'undefined' ? window.Telegram?.WebApp ?? null : null;
  const [, forceRender] = useState(0);

  useEffect(() => {
    if (!webApp) return;
    webApp.expand();
    const onThemeChanged = () => forceRender((n) => n + 1);
    webApp.onEvent('themeChanged', onThemeChanged);
    return () => webApp.offEvent('themeChanged', onThemeChanged);
  }, [webApp]);

  return { webApp, isTelegram: Boolean(webApp) };
}
