// src/hooks/useMainButton.ts
import { useEffect, useRef } from 'react';
import type { TelegramWebApp } from '../telegram';

interface MainButtonOptions {
  text: string;
  enabled: boolean;
  loading: boolean;
  onClick: () => void;
}

export function useMainButton(webApp: TelegramWebApp | null, options: MainButtonOptions) {
  const { text, enabled, loading, onClick } = options;
  const onClickRef = useRef(onClick);
  onClickRef.current = onClick;

  useEffect(() => {
    if (!webApp) return;
    const handler = () => onClickRef.current();
    webApp.MainButton.setText(text);
    webApp.MainButton.onClick(handler);
    webApp.MainButton.show();
    return () => {
      webApp.MainButton.offClick(handler);
      webApp.MainButton.hide();
    };
  }, [webApp, text]);

  useEffect(() => {
    if (!webApp) return;
    if (loading) {
      webApp.MainButton.showProgress(false);
    } else {
      webApp.MainButton.hideProgress();
      if (enabled) webApp.MainButton.enable();
      else webApp.MainButton.disable();
    }
  }, [webApp, enabled, loading]);
}
