import type { CartItem } from '../types';
import './CartSummary.css';

interface CartSummaryProps {
  items: CartItem[];
  deliveryFee: number;
}

export function CartSummary({ items, deliveryFee }: CartSummaryProps) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const total = subtotal + deliveryFee;

  return (
    <section className="cart-summary" aria-label="Order items">
      <h2 className="cart-summary__title">Your order</h2>
      <ul className="cart-summary__list">
        {items.map((item) => (
          <li key={item.id} className="cart-item">
            <div className="cart-item__image" aria-hidden={!item.imageUrl}>
              {item.imageUrl ? <img src={item.imageUrl} alt={item.name} /> : null}
            </div>
            <div className="cart-item__info">
              <span className="cart-item__name">{item.name}</span>
              <span className="cart-item__qty">Qty {item.quantity}</span>
            </div>
            <span className="cart-item__price">${(item.price * item.quantity).toFixed(2)}</span>
          </li>
        ))}
      </ul>
      <dl className="cart-summary__totals">
        <div className="cart-summary__row">
          <dt>Subtotal</dt>
          <dd>${subtotal.toFixed(2)}</dd>
        </div>
        <div className="cart-summary__row">
          <dt>Delivery</dt>
          <dd>${deliveryFee.toFixed(2)}</dd>
        </div>
        <div className="cart-summary__row cart-summary__row--total">
          <dt>Total</dt>
          <dd>${total.toFixed(2)}</dd>
        </div>
      </dl>
    </section>
  );
}
