// src/components/AddressForm.tsx
import type { DeliveryAddress } from '../types';
import './AddressForm.css';

export type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

interface AddressFormProps {
  value: DeliveryAddress;
  errors: AddressErrors;
  onChange: (next: DeliveryAddress) => void;
}

const FIELDS: Array<{
  key: keyof DeliveryAddress;
  label: string;
  placeholder: string;
  required: boolean;
  autoComplete?: string;
  type?: string;
}> = [
  { key: 'fullName', label: 'Full name', placeholder: 'Jane Doe', required: true, autoComplete: 'name' },
  { key: 'phone', label: 'Phone number', placeholder: '+1 555 000 0000', required: true, type: 'tel', autoComplete: 'tel' },
  { key: 'city', label: 'City', placeholder: 'New York', required: true, autoComplete: 'address-level2' },
  { key: 'street', label: 'Street', placeholder: 'Main Street', required: true, autoComplete: 'address-line1' },
  { key: 'house', label: 'House / Building', placeholder: '12', required: true },
  { key: 'apartment', label: 'Apartment (optional)', placeholder: '34', required: false },
  { key: 'postalCode', label: 'Postal code', placeholder: '10001', required: true, autoComplete: 'postal-code' },
  { key: 'comment', label: 'Delivery notes (optional)', placeholder: 'Leave at the door', required: false },
];

export function AddressForm({ value, errors, onChange }: AddressFormProps) {
  const setField = (key: keyof DeliveryAddress, fieldValue: string) => {
    onChange({ ...value, [key]: fieldValue });
  };

  return (
    <section className="address-form" aria-label="Delivery address">
      <h2 className="address-form__title">Delivery address</h2>
      {FIELDS.map((field) => (
        <div className="address-form__field" key={field.key}>
          <label className="address-form__label" htmlFor={field.key}>
            {field.label}
            {field.required ? <span className="address-form__required"> *</span> : null}
          </label>
          {field.key === 'comment' ? (
            <textarea
              id={field.key}
              className="address-form__input address-form__textarea"
              placeholder={field.placeholder}
              value={value[field.key]}
              onChange={(e) => setField(field.key, e.target.value)}
              rows={3}
            />
          ) : (
            <input
              id={field.key}
              className="address-form__input"
              type={field.type ?? 'text'}
              placeholder={field.placeholder}
              value={value[field.key]}
              autoComplete={field.autoComplete}
              onChange={(e) => setField(field.key, e.target.value)}
              aria-invalid={Boolean(errors[field.key])}
              aria-describedby={errors[field.key] ? `${field.key}-error` : undefined}
            />
          )}
          {errors[field.key] ? (
            <span className="address-form__error" id={`${field.key}-error`}>
              {errors[field.key]}
            </span>
          ) : null}
        </div>
      ))}
    </section>
  );
}
