```tsx
// src/screens/CheckoutScreen.tsx
import { useEffect, useMemo, useState } from 'react';
import { CartSummary } from '../components/CartSummary';
import { AddressForm, type AddressErrors } from '../components/AddressForm';
import { useTelegramWebApp } from '../hooks/useTelegramWebApp';
import { useBackButton } from '../hooks/useBackButton';
import { useMainButton } from '../hooks/useMainButton';
import { EMPTY_ADDRESS, type CartItem, type DeliveryAddress } from '../types';
import './CheckoutScreen.css';

const DELIVERY_FEE = 4.99;

interface CheckoutScreenProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void>;
}

function validate(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!address.phone.trim()) errors.phone = 'Enter a phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street';
  if (!address.house.trim()) errors.house = 'Enter a house number';
  if (!address.postalCode.trim()) errors.postalCode = 'Enter a postal code';
  return errors;
}

export function CheckoutScreen({ items, onBackToCart, onPay }: CheckoutScreenProps) {
  const { webApp, isTelegram } = useTelegramWebApp();
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState(false);
  const [isPaying, setIsPaying] = useState(false);

  const errors = useMemo(() => validate(address), [address]);
  const isValid = Object.keys(errors).length === 0;
  const isDirty = useMemo(
    () => Object.values(address).some((v) => v.trim().length > 0),
    [address]
  );

  useBackButton(webApp, onBackToCart);

  useEffect(() => {
    if (!webApp) return;
    if (isDirty) webApp.enableClosingConfirmation();
    else webApp.disableClosingConfirmation();
  }, [webApp, isDirty]);

  const handlePay = async () => {
    if (!isValid) {
      setTouched(true);
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }
    setIsPaying(true);
    try {
      await onPay(address);
      webApp?.HapticFeedback.notificationOccurred('success');
      webApp?.disableClosingConfirmation();
    } catch (err) {
      webApp?.HapticFeedback.notificationOccurred('error');
      const message = err instanceof Error ? err.message : 'Payment failed, please try again.';
      if (webApp) {
        webApp.showAlert(message);
      } else {
        window.alert(message);
      }
    } finally {
      setIsPaying(false);
    }
  };

  useMainButton(webApp, {
    text: isPaying ? 'Processing…' : 'Pay now',
    enabled: isValid && !isPaying,
    loading: isPaying,
    onClick: handlePay,
  });

  return (
    <div className="checkout">
      <div className="checkout__scroll">
        {!isTelegram && (
          <button type="button" className="checkout__back-fallback" onClick={onBackToCart}>
            ← Back to cart
          </button>
        )}

        <CartSummary items={items} deliveryFee={DELIVERY_FEE} />

        <AddressForm
          value={address}
          errors={touched ? errors : {}}
          onChange={(next) => {
            setTouched(true);
            setAddress(next);
          }}
        />
      </div>

      {!isTelegram && (
        <div className="checkout__footer">
          <button
            type="button"
            className="checkout__pay-fallback"
            disabled={!isValid || isPaying}
            onClick={handlePay}
          >
            {isPaying ? 'Processing…' : 'Pay now'}
          </button>
        </div>
      )}
    </div>
  );
}
